from PIL import Image
import numpy as np
from collections import deque
for name in ['reset_room.png','room_020.png','room_030.png','room_040.png','fail_room_camera.png']:
 a=np.asarray(Image.open('/tmp/'+name).convert('L'))
 m=(a>=140)&(a<=200)
 roi=m[155:235,90:225]
 H,W=roi.shape; seen=np.zeros_like(roi,bool); cs=[]
 for y in range(H):
  for x in range(W):
   if not roi[y,x] or seen[y,x]:continue
   q=[(y,x)];seen[y,x]=1; pts=[]
   while q:
    yy,xx=q.pop();pts.append((yy,xx))
    for dy in (-1,0,1):
     for dx in (-1,0,1):
      ny,nx=yy+dy,xx+dx
      if 0<=ny<H and 0<=nx<W and roi[ny,nx] and not seen[ny,nx]:seen[ny,nx]=1;q.append((ny,nx))
   if len(pts)>=5:
    p=np.asarray(pts); cs.append((len(p), (p[:,1].min()+90,p[:,0].min()+155,p[:,1].max()+90,p[:,0].max()+155), p.mean(0)[::-1]+[90,155]))
 cs.sort(reverse=True)
 print(name,cs[:10])
